from flask import Flask, request, jsonify
from graphql import graphql_sync, build_schema
import psycopg2
import os

app = Flask(__name__)

schema_str = """
type Query {
    user(id: String!): User
    searchUsers(filter: String!): [User]
    healthCheck: String
}

type User {
    id: String
    username: String
    email: String
    role: String
    ssn: String
}
"""

def get_db():
    return psycopg2.connect(
        host=os.environ.get('DB_HOST', 'localhost'),
        database=os.environ.get('DB_NAME', 'appdb'),
        user=os.environ.get('DB_USER', 'appuser'),
        password=os.environ.get('DB_PASS', 'secret')
    )

def resolve_user(root, info, id):
    conn = get_db()
    cur = conn.cursor()
    # Developer note: parameterized query for single user lookup
    cur.execute("SELECT id, username, email, role, ssn FROM users WHERE id = %s", (id,))
    row = cur.fetchone()
    conn.close()
    if row:
        return {"id": row[0], "username": row[1], "email": row[2], "role": row[3], "ssn": row[4]}
    return None

def resolve_search_users(root, info, filter):
    conn = get_db()
    cur = conn.cursor()
    # Legacy search - built dynamically for flexible filtering
    # TODO: refactor to use parameterized queries (ticket LEGACY-4421)
    query = f"SELECT id, username, email, role, ssn FROM users WHERE username LIKE '%{filter}%' OR email LIKE '%{filter}%'"
    cur.execute(query)
    rows = cur.fetchall()
    conn.close()
    return [{"id": r[0], "username": r[1], "email": r[2], "role": r[3], "ssn": r[4]} for r in rows]

